(() => {
  'use strict';
  const $ = (s,root=document)=>root.querySelector(s);
  const categories=window.FLOWER_CATEGORIES,products=window.FLOWER_PRODUCTS;
  const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const priceLabel=p=>p.price===null?'Цена по запросу':p.price.toLocaleString('ru-RU')+' ₽';
  const stockNote='Наличие, размер растения и актуальную стоимость уточняйте при заказе.';
  const key='nadezhda-favorites-v1';
  let saved;
  try { const raw=JSON.parse(localStorage.getItem(key)||'[]'); saved=new Set(Array.isArray(raw)?raw.filter(id=>products.some(p=>p.id===id)):[]); } catch { saved=new Set(); }
  const icon=(name)=>`<img class="icon" src="./assets/${name}.svg" alt="" width="22" height="22">`;
  const socialButtons=()=>`<div class="social-buttons"><a class="button primary max-trigger" href="https://max.ru/u/f9LHodD0cOKaOMjvuTLBEVfH1lGb5cDNrkHvBByFGdCg5YCWQJgUBWmQQRM" target="_blank" rel="noopener noreferrer"><img class="max-logo" src="./assets/max-logo-green.svg" alt="">Написать в MAX</a><a class="button secondary" href="https://ok.ru/profile/211714658759" target="_blank" rel="noopener noreferrer">${icon('odnoklassniki-green')}Одноклассники</a></div>`;
  const categoryCard=c=>`<a class="category-card" href="./catalog.html?category=${c.id}"><div class="category-photo"><img src="./assets/${c.id}.webp" alt="${c.short}" width="600" height="650" loading="lazy"><span class="category-overlay"><span class="category-view">Смотреть</span></span></div><div class="category-caption"><h3>${c.id==='other'?'Другие цветы':c.name}</h3></div></a>`;
  const productCard=p=>`<article class="product-card"><div class="product-photo"><button class="product-open" data-product="${p.id}" aria-label="Подробнее: ${safe(p.name)}"><img src="./assets/${p.image}.webp" alt="${safe(p.name)}" width="600" height="600" loading="lazy"></button><button class="favorite-button ${saved.has(p.id)?'is-saved':''}" data-favorite="${p.id}" aria-label="${saved.has(p.id)?'Убрать из избранного':'Добавить в избранное'}: ${safe(p.name)}" aria-pressed="${saved.has(p.id)}">${icon(saved.has(p.id)?'ph-heart-fill':'ph-heart')}</button></div><span class="sku">Артикул ${p.sku?safe(p.sku):'не указан'}</span><h3><button class="product-name" data-product="${p.id}">${safe(p.name)}</button></h3><p class="product-size">${safe(p.size)}</p><strong class="price ${p.price===null?'price-on-request':''}">${priceLabel(p)}</strong></article>`;
  const main=$('#main');
  function home(){
    document.title='Цветы Надежды — вегетативные цветы и рассада в Назарово';
    main.innerHTML=`<section class="hero shell"><div class="hero-copy"><span class="eyebrow">Коллекция нового сезона</span><h1>Вегетативные<br>петунии</h1><p>Цветы, в которые влюбляются.<br>Выберите свои оттенки для нового сезона.</p><a class="button primary" href="./catalog.html?category=petunia">Смотреть в каталоге</a></div><div class="hero-image"><img src="./assets/hero-petunia.webp" alt="Петунии из коллекции Надежды" width="1000" height="850" fetchpriority="high"></div></section>
    <section class="section shell" id="catalog"><div class="section-heading"><div><h2>Найдите свой цветок</h2><p>Для сада, балкона и маленькой радости каждый день.</p></div><span class="section-meta">8 категорий</span></div><div class="category-grid">${categories.map(categoryCard).join('')}</div></section>
    <section class="about shell section" id="about"><div class="about-photo"><img src="./assets/about-nadezhda-flowers.webp" alt="Цветы из коллекции Надежды" loading="lazy" width="1079" height="1080"></div><div class="about-copy"><span class="eyebrow">Давайте знакомиться</span><h2>Я Надежда.<br>И это мой цветочный мир.</h2><p>Моё увлечение цветами уже 8 лет растёт вместе с моей коллекцией — сегодня в ней более 300 растений. Я выращиваю вегетативные цветы из европейских черенков, внимательно ухаживаю за ними и каждый сезон пополняю ассортимент.</p><p>Здесь можно выбрать укоренённые черенки, рассаду и растения разного размера. Принимаю заказы круглый год и предлагаю цветы из наличия.</p><p>За каждым растением — мой опыт и дело, которое я люблю.</p></div></section>
    <section class="delivery section" id="delivery"><div class="shell"><div class="section-heading"><div><h2>Ближе, чем кажется</h2><p>Доставка и самовывоз</p></div></div><p class="delivery-intro">Мы осуществляем доставку по всему <strong>Красноярскому краю и Республике Хакасия</strong>, чтобы вы могли получить свой заказ максимально удобно.</p><div class="delivery-grid"><div class="delivery-option"><span class="delivery-icon">${icon('ph-truck')}</span><div><h3>Доставка</h3><p>Доставляем заказы в города и населённые пункты Красноярского края и Хакасии. Сроки и стоимость доставки рассчитываются индивидуально в зависимости от вашего местоположения.</p></div></div><div class="delivery-option"><span class="delivery-icon">${icon('ph-map-pin')}</span><div><h3>Самовывоз из Назарово</h3><p>Вы также можете самостоятельно забрать свой заказ в городе <strong>Назарово</strong>. Мы всегда рады самовывозу — просто согласуйте с нами удобное время получения.</p></div></div></div><div class="delivery-cta"><div><h3>Хотите оформить заказ или узнать стоимость доставки?</h3><p>Свяжитесь с нами прямо сейчас! Мы рассчитаем стоимость доставки до вашего населённого пункта, ответим на все вопросы и поможем выбрать самый удобный способ получения заказа.</p></div>${socialButtons()}</div></div></section>
    <section class="contacts section shell" id="contacts"><div><span class="eyebrow">Всегда на связи</span><h2>Поговорим<br>о ваших цветах?</h2><p>Сохраните понравившиеся растения в избранное<br class="desktop-break"> и напишите мне, чтобы оформить заказ.</p>${socialButtons()}</div><figure class="contact-map"><div class="contact-map-frame"><iframe title="Карта города Назарово — OpenStreetMap" src="https://www.openstreetmap.org/export/embed.html?bbox=90.325%2C55.98%2C90.51%2C56.045&amp;layer=mapnik&amp;marker=56.011593%2C90.418503" width="560" height="360" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><figcaption><span>г. Назарово, Красноярский край</span><a href="https://www.openstreetmap.org/?mlat=56.011593&amp;mlon=90.418503#map=12/56.011593/90.418503" target="_blank" rel="noopener noreferrer">Открыть карту</a></figcaption></figure></section>`;
  }
  function catalog(){
    const id=new URLSearchParams(location.search).get('category')||'petunia';
    const cat=categories.find(c=>c.id===id);
    if(!cat){main.innerHTML=`<section class="shell section empty"><h1>Категория не найдена</h1><a class="button primary" href="./index.html#catalog">Перейти в каталог</a></section>`;return;}
    document.title=cat.name+' | Цветы Надежды';
    main.innerHTML=`<section class="shell catalog-page"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="./index.html">Главная</a><span>/</span><a href="./index.html#catalog">Каталог</a><span>/</span><span>${cat.short}</span></nav><h1>${cat.name}</h1><p class="catalog-description">${cat.desc}</p><nav class="category-tabs" aria-label="Категории растений">${categories.map(c=>`<a href="./catalog.html?category=${c.id}" ${c.id===id?'aria-current="page"':''}>${c.short}</a>`).join('')}</nav><div class="catalog-toolbar"><span id="results-count">${products.filter(p=>p.category===id).length} ${plural(products.filter(p=>p.category===id).length)}</span><div class="catalog-controls"><label class="search-field">${icon('ph-magnifying-glass')}<input id="search" type="search" placeholder="Название или артикул" aria-label="Поиск по названию или артикулу"></label><label class="sort-label"><span class="visually-hidden">Сортировка</span><select id="sort"><option value="default">По умолчанию</option><option value="low">Сначала дешевле</option><option value="high">Сначала дороже</option><option value="name">По названию</option></select></label></div></div><div class="product-grid" id="products"></div><div class="catalog-order"><div><h2>Нашли свой цветок?</h2><p>Добавьте растения в избранное и напишите мне для заказа.<br>Помогу с выбором и расскажу о наличии.</p></div>${socialButtons()}</div></section>`;
    const render=()=>{const q=$('#search').value.toLocaleLowerCase('ru-RU').trim();let list=products.filter(p=>p.category===id&&`${p.name} ${p.sku||''}`.toLocaleLowerCase('ru-RU').includes(q));const sort=$('#sort').value;if(sort==='low')list.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(sort==='high')list.sort((a,b)=>(b.price??-Infinity)-(a.price??-Infinity));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ru'));$('#products').innerHTML=list.length?list.map(productCard).join(''):`<div class="empty search-empty">${products.some(p=>p.category===id)?'<h2>Ничего не нашлось</h2><p>Попробуйте другое название или артикул.</p><button class="button secondary" id="reset-search">Сбросить поиск</button>':'<h2>Здесь скоро появятся цветы</h2><p>Карточки этой категории ещё не добавлены.<br>Напишите Надежде, чтобы узнать о поступлении.</p><a class="button primary max-trigger" href="https://max.ru/u/f9LHodD0cOKaOMjvuTLBEVfH1lGb5cDNrkHvBByFGdCg5YCWQJgUBWmQQRM" target="_blank" rel="noopener noreferrer">Узнать о поступлении</a>'}</div>`;$('#results-count').textContent=`Найдено: ${list.length}`;};
    $('#search').addEventListener('input',render);$('#sort').addEventListener('change',render);render();
    main.addEventListener('click',e=>{if(e.target.closest('#reset-search')){$('#search').value='';render();}});
  }
  function favorites(){
    document.title='Избранное | Цветы Надежды';
    const list=products.filter(p=>saved.has(p.id));
    main.innerHTML=`<section class="shell catalog-page"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="./index.html">Главная</a><span>/</span><span>Избранное</span></nav><div class="section-heading"><div><h1>Ваш цветочный выбор</h1><p>Здесь живут растения, которые вам понравились.</p></div><span class="section-meta">${list.length} ${plural(list.length)}</span></div>${list.length?`<div class="product-grid">${list.map(productCard).join('')}</div><div class="favorites-summary"><div><h2>Сохраните список для заказа</h2><p>Скопируйте список с артикулами и отправьте Надежде.<br>Наличие и итоговую стоимость согласуем в переписке.</p></div><button class="button primary copy-list">${icon('ph-copy')}Скопировать список</button></div><div class="catalog-order"><div><h2>Осталось написать мне</h2><p>С радостью помогу с оформлением и доставкой.</p></div>${socialButtons()}</div>`:`<div class="empty">${icon('ph-heart')}<h2>Здесь расцветёт ваш выбор</h2><p>Нажимайте на сердечко у понравившихся растений.<br>Они сохранятся здесь, даже если вы закроете сайт.</p><a class="button primary" href="./index.html#catalog">Выбрать цветы ${icon('ph-arrow-right')}</a></div>`}</section>`;
  }
  function plural(n){return n%10===1&&n%100!==11?'растение':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'растения':'растений';}
  function updateCount(){$('.favorites-link>img').src=`./assets/ph-heart${saved.size?'-fill':''}.svg`;document.querySelectorAll('.favorite-count').forEach(el=>{el.textContent=saved.size;el.hidden=!saved.size;});$('.favorites-link').setAttribute('aria-label',`Избранное, ${saved.size} ${plural(saved.size)}`);}
  let toastTimer;function toast(text){const el=$('.toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000);}
  async function copy(text,success){try{await navigator.clipboard.writeText(text);toast(success);}catch{const dialog=document.createElement('dialog');dialog.className='copy-dialog';dialog.innerHTML=`<h2>Скопируйте текст</h2><textarea aria-label="Текст для копирования" readonly></textarea><button class="button primary">Готово</button>`;document.body.append(dialog);$('textarea',dialog).value=text;$('button',dialog).onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();$('textarea',dialog).select();}}
  function openProduct(id){const p=products.find(p=>p.id===id);if(!p)return;const dialog=document.createElement('dialog');dialog.className='product-dialog';dialog.setAttribute('aria-labelledby','product-title');dialog.innerHTML=`<button class="icon-button dialog-close" aria-label="Закрыть">${icon('ph-x')}</button><div class="detail-gallery"><img class="detail-photo" src="./assets/${p.image}.webp" alt="${safe(p.name)}" width="600" height="600">${p.images.length>1?`<div class="detail-thumbs">${p.images.map((image,i)=>`<button data-detail-image="${image}" aria-label="Фото ${i+1}" aria-pressed="${i===0}"><img src="./assets/${image}.webp" alt="Фото ${i+1}"></button>`).join('')}</div>`:''}</div><div class="detail-copy"><span class="sku">Артикул ${p.sku?safe(p.sku):'не указан'}</span><h2 id="product-title">${safe(p.name)}</h2><p>${safe(p.size)}</p><p class="original-description">${safe(p.description)}</p><strong class="price ${p.price===null?'price-on-request':''}">${priceLabel(p)}</strong><p class="sample-note">${stockNote}</p><button class="button secondary" data-favorite="${p.id}" aria-pressed="${saved.has(p.id)}">${icon(saved.has(p.id)?'ph-heart-fill':'ph-heart')}<span>${saved.has(p.id)?'В избранном':'В избранное'}</span></button><a class="button primary max-trigger" href="https://max.ru/u/f9LHodD0cOKaOMjvuTLBEVfH1lGb5cDNrkHvBByFGdCg5YCWQJgUBWmQQRM" target="_blank" rel="noopener noreferrer">Уточнить в MAX</a></div>`;document.body.append(dialog);$('.dialog-close',dialog).onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.addEventListener('click',e=>{if(e.target===dialog&&outsideDialog(e,dialog))dialog.close();});dialog.showModal();}
  function outsideDialog(e,d){const r=d.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom;}
  const page=location.pathname.split('/').pop();
  if(page==='catalog.html')catalog();else if(page==='favorites.html')favorites();else home();
  document.addEventListener('click',e=>{
    const thumb=e.target.closest('[data-detail-image]');if(thumb){const d=thumb.closest('dialog');$('.detail-photo',d).src='./assets/'+thumb.dataset.detailImage+'.webp';d.querySelectorAll('[data-detail-image]').forEach(b=>b.setAttribute('aria-pressed',String(b===thumb)));return;}
    const fav=e.target.closest('[data-favorite]');
    if(fav){const id=fav.dataset.favorite; saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem(key,JSON.stringify([...saved]));}catch{toast('Выбор сохранён только на время этого просмотра');}updateCount();document.querySelectorAll(`[data-favorite="${id}"]`).forEach(b=>{b.classList.toggle('is-saved',saved.has(id));b.setAttribute('aria-pressed',saved.has(id));const p=products.find(x=>x.id===id);b.setAttribute('aria-label',`${saved.has(id)?'Убрать из избранного':'Добавить в избранное'}: ${safe(p.name)}`);$('img.icon',b).src=`./assets/ph-heart${saved.has(id)?'-fill':''}.svg`;if($('span',b))$('span',b).textContent=saved.has(id)?'В избранном':'В избранное';});if(page==='favorites.html'){const next=products.filter(p=>saved.has(p.id));if(!next.length){document.querySelectorAll('.product-dialog').forEach(d=>d.close());favorites();}else{favorites();}}toast(saved.has(id)?'Растение добавлено в избранное':'Растение удалено из избранного');return;}
    if(e.target.closest('.copy-list')){const list=products.filter(p=>saved.has(p.id));copy(`Здравствуйте, Надежда! Интересуют растения:\n\n${list.map(p=>`Арт. ${p.sku||'не указан'}: ${p.name} (${p.price===null?'цена по запросу':p.price+' руб.'})`).join('\n')}\n\nПодскажите, пожалуйста, наличие и актуальную стоимость.`,'Список скопирован. Отправьте его Надежде.');return;}
    const open=e.target.closest('[data-product]');if(open)openProduct(open.dataset.product);
  });
  $('.menu-toggle').addEventListener('click',()=>{const menu=$('#mobile-menu');menu.hidden=!menu.hidden;$('.menu-toggle').setAttribute('aria-expanded',String(!menu.hidden));$('.menu-toggle').setAttribute('aria-label',menu.hidden?'Открыть меню':'Закрыть меню');});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#mobile-menu').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}});
  $('#mobile-menu').addEventListener('click',e=>{if(e.target.closest('a,button')){$('#mobile-menu').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}});
  const themeMedia=matchMedia('(prefers-color-scheme: dark)');let choice;try{choice=localStorage.getItem('nadezhda-theme');}catch{}
  function setTheme(value){document.documentElement.dataset.theme=value;const button=$('.theme-toggle');$('img',button).src=`./assets/ph-${value==='dark'?'sun':'moon'}.svg`;button.setAttribute('aria-label',value==='dark'?'Включить светлую тему':'Включить тёмную тему');}
  setTheme(choice|| (themeMedia.matches?'dark':'light'));
  $('.theme-toggle').addEventListener('click',()=>{choice=document.documentElement.dataset.theme==='dark'?'light':'dark';setTheme(choice);try{localStorage.setItem('nadezhda-theme',choice);}catch{}});
  themeMedia.addEventListener('change',()=>{if(!choice)setTheme(themeMedia.matches?'dark':'light');});
  window.addEventListener('storage',e=>{if(e.key===key){try{const raw=JSON.parse(e.newValue||'[]');saved=new Set(Array.isArray(raw)?raw.filter(id=>products.some(p=>p.id===id)):[]);updateCount();if(page==='favorites.html')favorites();else document.querySelectorAll('[data-favorite]').forEach(b=>{b.classList.toggle('is-saved',saved.has(b.dataset.favorite));b.setAttribute('aria-pressed',saved.has(b.dataset.favorite));$('img.icon',b).src=`./assets/ph-heart${saved.has(b.dataset.favorite)?'-fill':''}.svg`;const label=$('span',b);if(label)label.textContent=saved.has(b.dataset.favorite)?'В избранном':'В избранное';});}catch{}}});
  updateCount();
  if(location.hash)requestAnimationFrame(()=>$(location.hash)?.scrollIntoView());
})();
